from common import *
def p(no,*fields,why='',limited=False):row('problems-plus',no,*fields,why=why,limited=limited,suffix='-problems-plus-0')
p(1,c('All functions','f(x)=10e^x orf(x)=−10e^x'),why='Atx=0,f(0)²=100. Differentiate the integral identity:2ff′=f²+(f′)², hence(f′−f)²=0 everywhere. Thusf′=f and the two initial signs give exactly these functions; substitution confirms the original identity.')
p(2,c('All possible functions','g(x)=Ce^x√(2x−1), x>1/2, any real C','g(x)=Ce^(−x)√(2x−1), x>1/2','g(x)=Ce^x/√(2x−1), x>1/2'),why='The source hasf=e^(x²), not e^x. The equalityf′g+fg′=f′g′ gives(2x−1)g′=2xg; integrateg′/g=1+1/(2x−1). The zero function is included byC=0.')
p(3,c('Derivative identity','f′(x)=f(x)lim[h→0](f(h)−1)/h=f(x)'),c('Function','f(x)=e^x'),why='The multiplicative identity turns the difference quotient at arbitraryx into f(x) times the quotient at0. Sincef′(0)=1, the derivative exists everywhere and equalsf; f(0)=1 fixes the exponential constant.',limited=True)
p(4,c('All nonzero functions on a connected interval','f(x)=Ae^x orf(x)=Ae^(−x), A≠0'),c('Meaning of the indefinite integrals','There exist choices of antiderivative constants whose product is−1; arbitrary independent constants do not preserve it'),why='WriteF′=f,G′=1/f,FG=−1. Differentiating givesfG+F/f=0, soF²=f². Continuity and nonvanishing forceF=f orF=−f throughout a connected interval, hencef′=f orf′=−f. Corresponding primitives±f and∓1/f verify the product.')
p(5,c('Standard positive branch, n>0','f(x)=x^(1/n), x≥0'),c('Proportionality constant for that branch','n/(n+1)'),c('Nonuniqueness if only f≥0 is required','For any0≤a<1: f=0 on[0,a], andf=[(x−a)/(1−a)]^(1/n) forx>a'),c('Proportionality constant for delayed branch','n(1−a)/(n+1)'),why='Differentiating∫[0,x]f=kf^(n+1) on a positive interval gives(f^n)′=n/[k(n+1)]. The standard answer assumes positivity immediately after0. The literal nonnegative wording also permits a waiting interval; f(1)=1 then fixes its slope. We state n>0 and x≥0 because arbitrary real powers otherwise need domain conditions.',limited=True)
p(6,c('Curves, c>0','y=exp[(x−c)/c] andy=exp[−(x−c)/c]'),why='The horizontal subtangent length is|y/y′|=c, so on a smooth connected branchy′=±y/c. Through(c,1), the two signs give the two exponential curves. A positive length requiresc>0.')
p(7,n('Room temperature',20,'°C'),why='Equal ten-minute intervals have the same cooling factorq. Thus(80−T)²=(100−T)(65−T), givingT=20°C andq=3/4; this also reproduces65°C.')
b=(s.sqrt(5)-1)/2
p(8,n('Hours before noon snow began',b,'h',.00001),c('Clock time','Approximately11:22:55 am'),why='Constant snowfall makes depth proportionalt+b. Fixed volumetric removal givesx′=K/(t+b). Distances6and3km implyln[(b+1)/b]=2ln[(b+2)/(b+1)], henceb²+b−1=0 and its positive root. Subtract60b minutes fromnoon.')
p(9,c('(a) differential equation','xy″=√(1+(y′)²)'),c('(b) slope','y′=x/(2L)−L/(2x)'),c('(b) path','y=(x²−L²)/(4L)−(L/2)ln(x/L), 0<x≤L'),c('(c) capture','Never; the separation approachesL/2, not0'),why='The rabbit lies at the y-interceptY=y−xy′ of the pursuit tangent. Equal traveled speeds relate rabbit motion to dog arc length and give the stated DE. Setz=y′, integrateasinhz=ln(x/L), then integrate again usingy(L)=0. Separationx√(1+z²)=(x²+L²)/(2L) tendsL/2.',limited=True)
p(10,c('(a) equation, dog twice as fast','xy″=(1/2)√(1+(y′)²)'),c('(a) dog path','y=x^(3/2)/(3√L)−√(Lx)+2L/3'),c('(a) capture point','(0,2L/3)'),c('(b) minimum separation, dog half as fast','2L/3^(3/4)'),c('(b) dog position','(L/3^(1/4), L[5/3^(7/4)−2/3])'),c('(b) rabbit position','(0, L[8/3^(7/4)−2/3])'),why='For speed ratiok=vDog/vRabbit, asinhy′=(1/k)ln(x/L). Atk=1/2 the dog path isx³/(6L²)+L²/(2x)−2L/3 and the separation isx³/(2L²)+L²/(2x). Its unique minimum on0<x≤L occurs atx=L/3^(1/4). Rabbit ordinate isy−xy′.',limited=True)
p(11,n('(a) time from60ft to100ft',R(49,5),'h'),n('(b) uncovered floor area',31900*pi,'ft²',.01),n('(b) rate of covered-area growth',2000*pi,'ft²/h',.01),n('(c) time after loader starts at90ft',R(813,160),'h'),n('(c) total time from60ft with removal beginning at90ft',R(1839,160),'h'),why='Withr=1.5h, V=(3π/4)h³ andA=(9π/4)h². Before removalV′=60000π; after90ft it is40000π. Compute volume increments divided by their respective rates. The cone radius at100ft is150ft, below the silo200ft radius, so the conical model fits throughout.')
p(12,c('Curve','y=6/x, x>0'),why='If the tangent intercepts are(a,0),(0,b), midpointP=(x,y) impliesa=2x,b=2y. Tangent slope−b/a=−y/x gives(xy)′=0; through(3,2),xy=6.')
p(13,c('Implicit curve','x²+(y−6)²=25'),c('Graph branch through(3,2)','y=6−√(25−x²), −5<x<5'),why='The normal through(x,y) and(0,6) has slope(y−6)/x=−1/y′. Thereforex+(y−6)y′=0 and the curve is a circle centered(0,6); the given point fixes radius5. The lower graph branch contains(3,2).')
p(14,c('Nondegenerate curve family','2x²+y²=C, C>0'),why='If the y-axis bisects the normal segment from(x,y) to its x-intercept, that intercept is(−x,0). Normal slopey/(2x) givesy′=−2x/y; integration yields ellipses2x²+y²=C. Degenerate zero-length segments are excluded.',limited=True)
p(15,c('Nondegenerate curve branches','xy=C withC≠0'),why='The equal sides from(x,y) to(0,0) and to(a,0) requirea=2x (a=0 is the degenerate triangle). Tangent slope−y/x implies(xy)′=0. The nonzero condition excludes collapsed triangles on the axes.',limited=True)
# Independent differentiation, original identities and geometric checks.
z=10*s.exp(x);check('1 original integral',z*z-100-s.integrate(z*z+s.diff(z,x)**2,(x,0,x)))
f0=s.exp(x*x);g=s.exp(x)*s.sqrt(2*x-1);check('2 mistaken product equality',s.diff(f0*g,x)-s.diff(f0,x)*s.diff(g,x))
check('7 successive cooling',s.Integer(80-20)**2-(100-20)*(65-20))
check('8 snow logarithm algebra',(b+1)**3-b*(b+2)**2)
L=s.symbols('L',positive=True);u=s.symbols('u',positive=True)
for label,k,path in [('9',1,(u*u-L*L)/(4*L)-L*s.log(u/L)/2),('10a',2,u**R(3,2)/(3*s.sqrt(L))-s.sqrt(L*u)+2*L/3),('10b',R(1,2),u**3/(6*L*L)+L*L/(2*u)-2*L/3)]:
 slope=s.diff(path,u);check(label+' squared pursuit DE',(k*u*s.diff(slope,u))**2-1-slope*slope);check(label+' initial position',path.subs(u,L));check(label+' initial slope',slope.subs(u,L))
D=u**3/(2*L*L)+L*L/(2*u);star=L/3**R(1,4);check('10b minimum condition',s.diff(D,u).subs(u,star));check('10b minimum distance',D.subs(u,star)-2*L/3**R(3,4))
check('11a volume',(R(3,4)*(100**3-60**3))/60000-R(49,5));check('11c interval',(R(3,4)*(100**3-90**3))/40000-R(813,160))
check('11c total',R(3,4)*(90**3-60**3)/60000+R(813,160)-R(1839,160))
